 n=e['sourceOrder'];e['sixLiteralCanonicalGroups'][0]['individualGround']=cleanMain[n];e['sixLiteralCanonicalGroups'][1]['individualGround']=cleanExpl[n]
 for i in range(4):
  e['sixLiteralCanonicalGroups'][i+2]['individualGround']=cleanNotes[n][i];v=e['fourFullPromptAnswerNoteVariants'][i];v['grammar']='PASS: все варианты — последовательные самостоятельные именные подписи. Такая форма допустима для вопроса о названии/типе; грамматика не доказывает правильность смысловой категории. Справки грамматически самостоятельны.';v['plausibility']=cleanPlaus[n][i];v['truthUniqueKey']=cleanTruth[n][i];v['noteTruthUsefulness']=cleanNotes[n][i]
